package dev.aster.cosmetics;

import com.mojang.blaze3d.systems.RenderSystem;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.render.*;
import net.minecraft.block.enums.CameraSubmersionType;
import net.minecraft.entity.effect.StatusEffects;
import net.minecraft.world.World;
import org.joml.Matrix4f;

/** JVM render hook only. All original procedural geometry is generated by Rust. */
public final class AsterSky {
    public static void render(Matrix4f view,float delta,Camera camera,boolean thickFog) {
        MinecraftClient client=MinecraftClient.getInstance();
        var world=client.world;
        var c=AsterClient.CONFIG;
        if(world==null || !world.getRegistryKey().equals(World.OVERWORLD) || thickFog || camera.getSubmersionType()!=CameraSubmersionType.NONE) return;
        if(client.player!=null && (client.player.hasStatusEffect(StatusEffects.BLINDNESS)||client.player.hasStatusEffect(StatusEffects.DARKNESS))) return;
        java.util.ArrayList<Float> data=new java.util.ArrayList<>();
        for(var b:c.sky.bodies) { if(b==null||!b.enabled) continue; int rgb=CosmeticConfig.rgb(b.color); for(float v:new float[]{(float)b.azimuth,(float)b.elevation,(float)b.size,(rgb>>16)&255,(rgb>>8)&255,rgb&255})data.add(v); }
        float[] bodies=new float[data.size()];for(int i=0;i<bodies.length;i++)bodies[i]=data.get(i);
        float[] vertices=NativeCosmetics.advancedSky((world.getTime()+delta)/20.0,c.sky.starDensity,c.sky.meteorFrequency,c.sky.meteorSize,"aurora".equals(c.sky.preset)?2:1,c.sky.shootingStars,c.ui.reducedMotion,c.skyColor(),CosmeticConfig.rgb(c.sky.starColor),CosmeticConfig.rgb(c.sky.meteorColor),bodies);
        if(vertices==null || vertices.length==0) return;
        RenderSystem.disableDepthTest(); RenderSystem.depthMask(false); RenderSystem.disableCull(); RenderSystem.enableBlend(); RenderSystem.defaultBlendFunc();
        RenderSystem.setShader(GameRenderer::getPositionColorProgram); RenderSystem.setShaderColor(1,1,1,1);
        try {
            BufferBuilder builder=Tessellator.getInstance().begin(VertexFormat.DrawMode.QUADS,VertexFormats.POSITION_COLOR);
            for(int i=0;i+6<vertices.length;i+=7) builder.vertex(view,vertices[i],vertices[i+1],vertices[i+2]).color((int)vertices[i+3],(int)vertices[i+4],(int)vertices[i+5],(int)vertices[i+6]);
            BufferRenderer.drawWithGlobalProgram(builder.end());
        } finally {
            RenderSystem.setShaderColor(1,1,1,1); RenderSystem.disableBlend(); RenderSystem.enableCull(); RenderSystem.depthMask(true); RenderSystem.enableDepthTest();
        }
    }
}
